export interface IPDResult {
  ipdMm: number; // Final average
  limbusDistanceMm: number;
  pupilDistanceMm: number;
  confidence: number;
  confidenceInterval: string; // e.g. "95%"
  rightOuterLimbus: [number, number]; // [x, y] in 0-1000 scale
  leftInnerLimbus: [number, number];
  rightPupilCenter: [number, number];
  leftPupilCenter: [number, number];
  cardCorners?: [number, number][]; // Coordinates for the calibration card
  pixelDistanceLimbus: number;
  pixelDistancePupil: number;
  scalingFactor: number;
  calibrationUsed: 'card' | 'average_iris' | 'estimation';
  explanation: string;
}

export type ScanStatus = 'idle' | 'capturing' | 'analyzing' | 'completed' | 'error';

import { GoogleGenAI, Type } from "@google/genai";
import { IPDResult } from "../types";

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        parts: [
          {
            text: `Act as a clinical ophthalmic diagnostic AI. Your mission is to calculate the Interpupillary Distance (IPD) with extreme precision from the provided image.

CALIBRATION STRATEGY:
1. MANDATORY: Search for a standard ID/Credit card (ISO/IEC 7810 ID-1 standard width: 85.6mm).
2. If no card is found, use the standard adult iris diameter (Horizontal Visible Iris Diameter - HVID) of 11.7mm as the secondary reference.
3. If neither is present, use a demographic-weighted estimation (approx 63mm adult average) but flag it in the explanation.

MEASUREMENT PROTOCOL (Pixel-level accuracy required):
- L1 (Right Outer Limbus): The temporal (ear-side) border of the right iris/sclera junction.
- L2 (Left Inner Limbus): The nasal (nose-side) border of the left iris/sclera junction.
- L3 (Right Pupil Center): The geometric center of the right pupil.
- L4 (Left Pupil Center): The geometric center of the left pupil.

CALCULATION LOGIC:
- ScalingFactor (SF) = [Reference Dimension in mm] / [Reference Dimension in Pixels].
- IPD_Limbus = EuclideanDistance(L1, L2) * SF.
- IPD_Pupil = EuclideanDistance(L3, L4) * SF.
- Final IPD (ipdMm) = (IPD_Limbus + IPD_Pupil) / 2.
- Report all distances in millimeters (mm).

CONFIDENCE:
- The confidence interval must be set to 95% for clinical reporting.

OUTPUT FORMAT:
Provide a JSON object. Coordinates must be on a scale of 0-1000 (0,0 is top-left).`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER, description: "Final calculated IPD in mm (Average of Limbus and Pupil distances)" },
          limbusDistanceMm: { type: Type.NUMBER, description: "Distance between right outer and left inner limbus in mm" },
          pupilDistanceMm: { type: Type.NUMBER, description: "Distance between pupil centers in mm" },
          pixelDistanceLimbus: { type: Type.NUMBER },
          pixelDistancePupil: { type: Type.NUMBER },
          scalingFactor: { type: Type.NUMBER, description: "The calculated mm per pixel ratio" },
          confidence: { type: Type.NUMBER, description: "Measurement reliability score (0-1)" },
          confidenceInterval: { type: Type.STRING, description: "Should always be '95%'" },
          rightOuterLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER }, description: "[x, y]" },
          leftInnerLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          rightPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          leftPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          cardCorners: { 
            type: Type.ARRAY, 
            items: { type: Type.ARRAY, items: { type: Type.NUMBER } },
            description: "Optional 4 corners of the calibration card if used"
          },
          calibrationUsed: { type: Type.STRING, enum: ["card", "average_iris", "estimation"] },
          explanation: { type: Type.STRING }
        },
        required: ["ipdMm", "limbusDistanceMm", "pupilDistanceMm", "rightOuterLimbus", "leftInnerLimbus", "rightPupilCenter", "leftPupilCenter", "scalingFactor", "explanation", "calibrationUsed", "confidenceInterval"]
      }
    }
  });

  const result = JSON.parse(response.text || "{}");
  return result as IPDResult;
}

