  ipdMm: number; // Final average
  limbusDistanceMm: number;
  pupilDistanceMm: number;
  confidence: number;
  confidenceInterval: string; // e.g. "95%"
  rightOuterLimbus: [number, number]; // [x, y] in 0-1000 scale
  leftInnerLimbus: [number, number];
  rightPupilCenter: [number, number];
  leftPupilCenter: [number, number];
  pixelDistanceLimbus: number;
  pixelDistancePupil: number;
  scalingFactor: number;
  calibrationUsed: 'bio_metric' | 'proportional_rule' | 'reference_object';
  explanation: string;
}

export type ScanStatus = 'idle' | 'capturing' | 'analyzing' | 'completed' | 'error';

import { GoogleGenAI, Type } from "@google/genai";
import { IPDResult } from "../types";

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        parts: [
          {
            text: `Act as a clinical ophthalmic diagnostic AI specializing in Bio-Metric Proportional Analysis. 

Your task is to calculate the Interpupillary Distance (IPD) using the "Biological Scaling Rule":
1. PRIMARY RULE (HVID): The Horizontal Visible Iris Diameter (HVID) is a biological constant averaging 11.7mm in human adults. Use this as the primary anchor for spatial scaling.
2. SECONDARY RULE (Proportional Cross-Check): Verify the result against the "Human Average Rule" (63mm for males, 61mm for females). If the HVID-based calculation deviates by >15%, apply a weighted proportional correction based on facial width ratios.
3. LANDMARKS: 
   - L1 (Right Outer Limbus): Ear-side junction of iris/sclera.
   - L2 (Left Inner Limbus): Nose-side junction of iris/sclera.
   - L3/L4: Geometric centers of pupils.

CALCULATION:
- SF = 11.7 / [Measured Iris Width in Pixels].
- IPD = EuclideanDistance(L3, L4) * SF.

OUTPUT: Return a JSON object with coordinates on a 0-1000 scale.`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER },
          limbusDistanceMm: { type: Type.NUMBER },
          pupilDistanceMm: { type: Type.NUMBER },
          pixelDistanceLimbus: { type: Type.NUMBER },
          pixelDistancePupil: { type: Type.NUMBER },
          scalingFactor: { type: Type.NUMBER },
          confidence: { type: Type.NUMBER },
          confidenceInterval: { type: Type.STRING },
          rightOuterLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          leftInnerLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          rightPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          leftPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          calibrationUsed: { type: Type.STRING, enum: ["bio_metric", "proportional_rule", "reference_object"] },
          explanation: { type: Type.STRING }
        },
        required: ["ipdMm", "limbusDistanceMm", "pupilDistanceMm", "rightOuterLimbus", "leftInnerLimbus", "rightPupilCenter", "leftPupilCenter", "scalingFactor", "explanation", "calibrationUsed", "confidenceInterval"]
      }
    }
  });

  const result = JSON.parse(response.text || "{}");
  return result as IPDResult;
}

