import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { IPDResult } from "../types";

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {
          text: `Act as a Clinical Computer Vision Engineer specializing in TrueDepth-style spatial facial reconstruction.

MEASUREMENT GOAL: 
Calculate the Interpupillary Distance (IPD) using "Spatial Perspective Analysis". The user was instructed to fixate on a central target to ensure Far-Distance PD alignment.

SPATIAL CALIBRATION PROTOCOL:
1. DEPTH ESTIMATION (Z-Axis): Analyze the elliptical foreshortening of the irises. A circular iris has an HVID of 11.7mm. If the iris appears elliptical, calculate the tilt angle (Theta) and compensate the spatial scale accordingly.
2. GAZE NORMALIZATION: The user is looking at a fixation target. Use this gaze vector to ensure the Euclidean distance between pupil centers reflects a parallel optical axis (Far PD).
3. CLINICAL VALIDATION: Ensure results are audited against the 59.5mm - 75mm standard.

IDENTIFY:
- Right/Left Outer & Inner Limbus (for HVID scaling)
- Right/Left Pupil Geometric Centers (Euclidean midpoint)

CALCULATION:
- TrueHVID_Pixels = MajorAxis(Iris_Ellipse)
- ScalingFactor = 11.7 / TrueHVID_Pixels
- IPD_Raw = EuclideanDistance(Pupil_Centers) * ScalingFactor
- IPD_Corrected = IPD_Raw / cos(Head_Tilt_Angle)

OUTPUT:
Return JSON only. Coordinates must be on a 0-1000 scale. The explanation should detail the 'Spatial Depth Correction' and 'Gaze Fixation' status.`
        },
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image
          }
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER },
          limbusDistanceMm: { type: Type.NUMBER },
          pupilDistanceMm: { type: Type.NUMBER },
          pixelDistanceLimbus: { type: Type.NUMBER },
          pixelDistancePupil: { type: Type.NUMBER },
          scalingFactor: { type: Type.NUMBER },
          confidence: { type: Type.NUMBER },
          confidenceInterval: { type: Type.STRING },
          rightOuterLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          leftInnerLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          rightPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          leftPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          calibrationUsed: { type: Type.STRING },
          explanation: { type: Type.STRING }
        },
        required: [
          "ipdMm", "limbusDistanceMm", "pupilDistanceMm", 
          "rightOuterLimbus", "leftInnerLimbus", "rightPupilCenter", 
          "leftPupilCenter", "scalingFactor", "explanation", 
          "calibrationUsed", "confidenceInterval", "confidence", 
          "pixelDistanceLimbus", "pixelDistancePupil"
        ]
      }
    }
  });

  const result = JSON.parse(response.text || "{}");
  return result as IPDResult;
}

