                <div className="px-5 py-3 rounded-2xl bg-black/40 backdrop-blur-md border border-white/10 text-right">
                  <span className="text-[9px] font-black text-white/40 uppercase tracking-widest block mb-1">Live PD Estimate</span>
                  <div className="text-3xl font-black text-emerald-400 flex items-baseline gap-1">
                    {liveIPD ? liveIPD.toFixed(1) : '--.-'}
                    <span className="text-xs text-emerald-600/60 uppercase">mm</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex flex-col items-center gap-6">
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest flex items-center gap-2">
                <Info size={14} className="text-emerald-500" />
