export default function App() {
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [result, setResult] = useState<IPDResult | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Chat state
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [currentMessage, setCurrentMessage] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Real-time states
  const [liveIPD, setLiveIPD] = useState<number | null>(null);
  const [isPreCalibrating, setIsPreCalibrating] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const preCalibrateIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatMessages, isChatLoading]);

  const captureFrame = useCallback(async (isFinal = true) => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.9);

        if (isFinal) {
          setCapturedImage(dataUrl);
          if (videoRef.current.srcObject) {
            (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
          }
          processFinalImage(dataUrl);
        }
        return dataUrl;
      }
    }
    return null;
  }, []);

  const processFinalImage = async (dataUrl: string) => {
    try {
      setStatus('analyzing');
      const analysis = await analyzeIPD(dataUrl.split(',')[1]);
      setResult(analysis);
      setStatus('completed');
    } catch (err) {
      setError("Spatial reconstruction failed. Ensure lighting is uniform and you are looking directly at the crosshair.");
      setStatus('error');
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentMessage.trim() || isChatLoading || !result || !capturedImage) return;

    const userMsg = currentMessage;
    setCurrentMessage('');
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsChatLoading(true);

    try {
      const aiResponse = await chatWithExpert(
        userMsg, 
        chatMessages, 
        result.ipdMm, 
        capturedImage.split(',')[1]
      );
      setChatMessages(prev => [...prev, { role: 'model', text: aiResponse }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { role: 'model', text: "I'm sorry, I encountered an error connecting to my neural core. Please try again." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  // Pre-calibration logic (Flash-Lite)
  const runPreCalibration = useCallback(async () => {
    if (status !== 'capturing' || isPreCalibrating) return;

    const frame = await captureFrame(false);
    if (frame) {
      setIsPreCalibrating(true);
      try {
        const estimate = await preCalibrateIPD(frame.split(',')[1]);
        setLiveIPD(estimate.ipdMm);
      } catch (e) {
        // Silently fail pre-cal
      } finally {
        setIsPreCalibrating(false);
      }
    }
  }, [status, isPreCalibrating, captureFrame]);

  useEffect(() => {
    if (status === 'capturing') {
      preCalibrateIntervalRef.current = setInterval(runPreCalibration, 4000);
    } else {
      if (preCalibrateIntervalRef.current) clearInterval(preCalibrateIntervalRef.current);
      setLiveIPD(null);
    }
    return () => {
      if (preCalibrateIntervalRef.current) clearInterval(preCalibrateIntervalRef.current);
    };
  }, [status, runPreCalibration]);

  const startCamera = async () => {
    try {
      setStatus('capturing');
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      setError("Camera unavailable. Please check device permissions.");
      setStatus('idle');
    }
  };

  const reset = () => {
    setStatus('idle');
    setResult(null);
    setCapturedImage(null);
    setError(null);
    setChatMessages([]);
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
  };

  const isOutOfRange = result && (result.ipdMm < 59.5 || result.ipdMm > 75);

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 selection:bg-emerald-100">
      <Header />

      <main className="flex-grow max-w-6xl mx-auto w-full px-4 py-8 md:py-16">
        {status === 'idle' && (
          <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700">
            <div className="mb-12 md:mb-16">
              <div className="inline-flex items-center gap-2 px-3 py-1 bg-white border border-slate-200 rounded-full mb-6">
                <Sparkles size={12} className="text-emerald-500" />
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Advanced Spatial Sensors Ready</span>
              </div>
              <h1 className="text-5xl md:text-7xl font-black text-slate-900 mb-6 tracking-tight leading-[0.95]">
                Bio-Metric <br/>
                <span className="text-emerald-600">Manual-PD.</span>
              </h1>
              <p className="text-lg md:text-xl text-slate-500 leading-relaxed mb-10 max-w-xl">
                Precision measurement with live AI calibration. Validated clinical accuracy powered by Gemini Spatial Intelligence.
              </p>

              <div className="flex flex-col sm:flex-row gap-4">
                <button 
                  onClick={startCamera}
                  className="px-10 py-5 bg-emerald-600 text-white font-bold rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
                >
                  <Camera size={24} className="group-hover:rotate-12 transition-transform" />
                  Launch Scanner
                </button>
                <div className="relative">
                  <input type="file" accept="image/*" onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const r = new FileReader();
                      r.onload = (ev) => { setCapturedImage(ev.target?.result as string); processFinalImage(ev.target?.result as string); };
                      r.readAsDataURL(file);
                    }
                  }} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                  <button className="w-full sm:w-auto px-10 py-5 bg-white text-slate-700 font-bold rounded-2xl border border-slate-200 hover:bg-slate-50 transition-all flex items-center justify-center gap-3 shadow-sm">
                    <Upload size={22} />
                    Upload Image
                  </button>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { icon: <Target className="text-emerald-600" />, title: "Precision Target", desc: "Align your gaze with the central crosshair for high-accuracy Far-PD measurement." },
                { icon: <Activity className="text-emerald-600" />, title: "Live Calibration", desc: "Real-time estimations provide instant feedback during the manual scan process." },
                { icon: <ShieldCheck className="text-emerald-600" />, title: "Clinical Standards", desc: "Verified against ISO-13666 standards for ophthalmic measurements." }
              ].map((item, i) => (
                <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                  <div className="mb-4">{item.icon}</div>
                  <h3 className="font-bold text-slate-900 mb-2 uppercase text-[11px] tracking-wider">{item.title}</h3>
                  <p className="text-slate-500 leading-relaxed text-xs">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {status === 'capturing' && (
          <div className="max-w-4xl mx-auto animate-in zoom-in-95 duration-500 flex flex-col gap-8">
            <div className="relative aspect-[3/4] sm:aspect-video bg-slate-950 rounded-[3rem] overflow-hidden border-4 md:border-8 border-white shadow-2xl ring-1 ring-slate-100">
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover scale-x-[-1]" />

              <div className="absolute inset-0 pointer-events-none">
                <SpatialMeshOverlay />
                <div className="w-full h-full border-[20px] sm:border-[50px] md:border-[80px] border-black/40">
                  <div className="w-full h-full border-2 border-dashed border-white/10 rounded-[2.5rem] relative">
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[85%] sm:w-80 h-[45%] sm:h-56 border-2 border-emerald-400/20 rounded-[3rem] shadow-[0_0_50px_rgba(52,211,153,0.05)]" />
                    <div className="absolute top-0 left-0 right-0 h-0.5 bg-emerald-400/80 scanner-line" />
                  </div>
                </div>
              </div>

              <FixationTarget />

              {/* Live Tracking Overlay */}
              <div className="absolute top-6 left-6 right-6 flex justify-between items-start pointer-events-none">
                <div className="px-4 py-2 rounded-xl backdrop-blur-md border border-white/20 bg-black/40 text-white/70 flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-white/50 animate-pulse" />
                  <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                    Awaiting Manual Capture...
                  </span>
                </div>

                <div className="px-5 py-3 rounded-2xl bg-black/40 backdrop-blur-md border border-white/10 text-right">
                  <span className="text-[9px] font-black text-white/40 uppercase tracking-widest block mb-1">Live Auto-Calibration</span>
                  <div className="text-3xl font-black text-emerald-400 flex items-baseline gap-1">
                    {liveIPD ? liveIPD.toFixed(1) : '--.-'}
                    <span className="text-xs text-emerald-600/60 uppercase">mm</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex flex-col items-center gap-6">
              <div className="flex gap-4">
                <button 
                  onClick={() => captureFrame(true)}
                  className="px-12 py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 hover:scale-105 active:scale-95 transition-all flex items-center gap-3"
                >
                  <Target size={24} />
                  Capture Now
                </button>
                <button 
                  onClick={reset} 
                  className="px-10 py-5 bg-white text-slate-700 font-bold rounded-2xl border border-slate-200 hover:bg-slate-50 transition-all shadow-sm"
                >
                  Cancel
                </button>
              </div>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest flex items-center gap-2">
                <Info size={14} className="text-emerald-500" />
                Hold steady and look at the crosshair before clicking
              </p>
            </div>
          </div>
        )}

        {status === 'analyzing' && (
          <div className="max-w-md mx-auto text-center py-24 flex flex-col items-center animate-in fade-in duration-700">
            <div className="w-24 h-24 relative mb-10">
              <div className="absolute inset-0 border-4 border-emerald-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-emerald-600 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <Activity size={32} className="text-emerald-600 animate-pulse" />
              </div>
            </div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter mb-4">Spatial Refinement</h2>
            <div className="space-y-2 text-slate-400 text-xs font-bold uppercase tracking-widest">
              <p>Thinking deeply about your facial mesh...</p>
              <p>Reconstructing 3D Spatial Lattice...</p>
              <p>Verifying Euclidean Gaze Axis...</p>
            </div>
          </div>
        )}

        {status === 'completed' && result && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 md:gap-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="lg:col-span-5 space-y-8">
              <div className="relative aspect-square bg-slate-900 rounded-[3rem] overflow-hidden shadow-2xl border-[8px] border-white group">
                <img src={capturedImage!} alt="Analysis" className="w-full h-full object-cover opacity-90" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent"></div>

                {/* Visualizer Overlays */}
                <div className="absolute w-5 h-5 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full bg-emerald-500 shadow-[0_0_20px_#10b981] z-20" style={{ left: `${result.rightPupilCenter[0]/10}%`, top: `${result.rightPupilCenter[1]/10}%` }}></div>
                <div className="absolute w-5 h-5 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full bg-emerald-500 shadow-[0_0_20px_#10b981] z-20" style={{ left: `${result.leftPupilCenter[0]/10}%`, top: `${result.leftPupilCenter[1]/10}%` }}></div>

                <svg className="absolute inset-0 w-full h-full pointer-events-none z-10">
                  <line x1={`${result.rightPupilCenter[0]/10}%`} y1={`${result.rightPupilCenter[1]/10}%`} x2={`${result.leftPupilCenter[0]/10}%`} y2={`${result.leftPupilCenter[1]/10}%`} stroke="white" strokeWidth="2" strokeDasharray="10,5" />
                </svg>

                <div className="absolute bottom-6 left-6 right-6 p-4 bg-black/40 backdrop-blur-xl rounded-2xl border border-white/10 flex justify-between items-center">
                  <div className="text-[10px] font-black text-white uppercase tracking-widest flex items-center gap-2">
                    <Target size={14} /> Clinical Audit Trail
                  </div>
                </div>
              </div>

              {/* AI Chat Consultation Interface */}
              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden flex flex-col h-[500px]">
                <div className="p-6 border-b border-slate-50 bg-slate-50/50 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-emerald-100 rounded-xl flex items-center justify-center text-emerald-600">
                      <Sparkles size={20} />
                    </div>
                    <div>
                      <h4 className="text-sm font-black text-slate-900 uppercase tracking-tight leading-none">AI Consultant</h4>
                      <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Thinking Ready</span>
                    </div>
                  </div>
                </div>

                <div className="flex-grow overflow-y-auto p-6 space-y-4 bg-slate-50/20">
                  {chatMessages.length === 0 && (
                    <div className="text-center py-10 opacity-50">
                      <MessageSquare className="mx-auto mb-3 text-slate-300" size={32} />
                      <p className="text-xs font-bold uppercase tracking-widest text-slate-400 px-10 leading-relaxed">
                        Ask about frame recommendations or your IPD results
                      </p>
                    </div>
                  )}
                  {chatMessages.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[85%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm border ${
                        msg.role === 'user' 
                        ? 'bg-emerald-600 text-white border-emerald-500 rounded-tr-none' 
                        : 'bg-white text-slate-700 border-slate-100 rounded-tl-none'
                      }`}>
                        {msg.text}
                      </div>
                    </div>
                  ))}
                  {isChatLoading && (
                    <div className="flex justify-start">
                      <div className="bg-white p-4 rounded-2xl border border-slate-100 rounded-tl-none flex items-center gap-3">
                        <Loader2 className="animate-spin text-emerald-500" size={16} />
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest animate-pulse">Thinking...</span>
                      </div>
                    </div>
                  )}
                  <div ref={chatEndRef} />
                </div>

                <form onSubmit={handleSendMessage} className="p-4 bg-white border-t border-slate-50 flex gap-2">
                  <input
                    type="text"
                    value={currentMessage}
                    onChange={(e) => setCurrentMessage(e.target.value)}
                    placeholder="Ask about your vision..."
                    className="flex-grow bg-slate-50 border-none rounded-xl px-4 py-3 text-xs font-medium focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
                  />
                  <button 
                    disabled={!currentMessage.trim() || isChatLoading}
                    className="w-10 h-10 bg-emerald-600 text-white rounded-xl flex items-center justify-center hover:bg-emerald-700 disabled:opacity-50 disabled:bg-slate-400 transition-all shrink-0 shadow-lg shadow-emerald-100"
                  >
                    <Send size={18} />
                  </button>
                </form>
              </div>
            </div>

            <div className="lg:col-span-7 space-y-8">
              <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-xl border border-slate-100 relative overflow-hidden">
                <div className="flex items-center justify-between mb-8">
                  <span className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.2em]">Interpupillary Distance</span>
                  <div className={`px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${isOutOfRange ? 'bg-orange-100 text-orange-700' : 'bg-emerald-100 text-emerald-700'}`}>
                    {isOutOfRange ? 'Outside Standard' : 'Far-PD Verified'}
                  </div>
                </div>

                <div className="flex items-baseline gap-4 mb-10">
                  <span className={`text-9xl font-black tracking-tighter leading-none ${isOutOfRange ? 'text-orange-500' : 'text-slate-900'}`}>
                    {result.ipdMm.toFixed(1)}
                  </span>
                  <span className="text-3xl font-bold text-slate-200 italic uppercase">mm</span>
                </div>

                <div className="grid grid-cols-2 gap-6 mb-10">
                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Precision Scaling</span>
                    <div className="text-2xl font-black text-slate-800">{result.scalingFactor.toFixed(3)}</div>
                  </div>
                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Confidence Score</span>
                    <div className="text-2xl font-black text-emerald-600">{(result.confidence * 100).toFixed(1)}<span className="text-xs ml-0.5">%</span></div>
                  </div>
                </div>

                <div className="bg-slate-900 p-6 rounded-[2rem] flex flex-col sm:flex-row items-center justify-between gap-6">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-emerald-900/40">
                      <ShieldCheck size={24} />
                    </div>
                    <div>
                      <div className="text-white text-sm font-bold">Standard: ISO-13666 Clinical</div>
                      <div className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Model: Gemini 3 Pro (Thinking)</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 text-emerald-400 font-black text-xs uppercase tracking-widest bg-emerald-400/10 px-4 py-2 rounded-xl border border-emerald-400/20">
                    Validated
                    <CheckCircle size={14} />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <button 
                  onClick={reset} 
                  className="py-7 bg-emerald-600 text-white font-black text-xl rounded-[2.5rem] hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 shadow-2xl shadow-emerald-100 group"
                >
                  <RefreshCw size={24} className="group-hover:rotate-180 transition-transform duration-1000" />
                  New Scan
                </button>
                <button className="py-7 bg-white text-slate-900 font-bold text-lg rounded-[2.5rem] border-2 border-slate-100 hover:bg-slate-50 transition-all flex items-center justify-center gap-2">
                  <ChevronRight size={20} className="text-slate-300" />
                  Full Report
                </button>
              </div>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[3.5rem] border border-red-50 shadow-2xl text-center animate-in zoom-in-95 duration-500">
            <div className="w-20 h-20 bg-red-50 text-red-500 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-inner"><AlertCircle size={40} /></div>
            <h2 className="text-3xl font-black text-slate-900 mb-4 tracking-tight">Spatial Error</h2>
            <p className="text-slate-500 mb-10 leading-relaxed max-w-sm mx-auto">{error}</p>
            <button onClick={reset} className="w-full py-5 bg-slate-900 text-white font-bold rounded-2xl hover:bg-black transition-all">Try Again</button>
          </div>
        )}
      </main>

      <Footer />
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Camera, Upload, RefreshCw, Info, CheckCircle, AlertCircle, Target, Scan, ShieldCheck, Fingerprint, Activity, ChevronRight, Grid3X3, Layers, Sun, User, Minimize, Crosshair, Eye, Sparkles, MessageSquare, Send, Loader2 } from 'lucide-react';
import { ScanStatus, IPDResult } from './types';
import { analyzeIPD, chatWithExpert } from './services/geminiService';

const Header = () => (
  <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-50">
    <div className="max-w-6xl mx-auto px-6 h-16 md:h-20 flex items-center justify-between">
      <div className="flex items-center gap-3">
        <div className="w-9 h-9 bg-emerald-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-emerald-100">
          <Fingerprint size={20} />
        </div>
        <div>
          <span className="font-bold text-lg tracking-tight text-slate-900 block leading-none">VisionMetric</span>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">TrueDepth Spatial Analysis</span>
        </div>
      </div>
      <div className="hidden md:flex items-center gap-4">
        <div className="px-3 py-1 bg-emerald-50 text-emerald-700 text-[10px] font-bold rounded-full border border-emerald-100 uppercase tracking-widest">
          Spatial Sync Active
        </div>
      </div>
    </div>
  </header>
);

const Footer = () => (
  <footer className="mt-auto py-8 px-6 border-t border-slate-100 bg-white">
    <div className="max-w-6xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4 text-slate-400 text-[11px] font-medium uppercase tracking-wider">
      <p>© 2026 VisionMetric Labs. 3D Spatial Reconstruction Protocol.</p>
      <div className="flex gap-6">
        <a href="#" className="hover:text-emerald-600 transition-colors">Privacy</a>
        <a href="#" className="hover:text-emerald-600 transition-colors">Terms</a>
      </div>
    </div>
  </footer>
);

const SpatialMeshOverlay = () => (
  <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-20">
    <div className="absolute inset-0" style={{ 
      backgroundImage: `radial-gradient(circle, #34d399 1px, transparent 1px)`, 
      backgroundSize: '30px 30px' 
    }} />
    <div className="w-full h-full animate-pulse flex items-center justify-center">
      <div className="w-[80%] h-[80%] border border-emerald-400/30 rounded-full" />
      <div className="absolute w-[60%] h-[60%] border border-emerald-400/20 rounded-full" />
    </div>
  </div>
);

const FixationTarget = () => (
  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center justify-center z-30 pointer-events-none">
    <div className="relative">
      <div className="w-16 h-16 border-2 border-white/20 rounded-full absolute inset-0 transition-all duration-500 scale-100" />
      <div className="w-16 h-16 border-2 border-white/40 rounded-full flex items-center justify-center backdrop-blur-sm bg-black/20">
        <Crosshair className="text-white/60 size-8" />
      </div>
    </div>
    <div className="mt-6 px-4 py-2 text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-full shadow-lg border bg-black/40 border-white/20 flex items-center gap-2">
      <Eye className="size-3" /> Fixate on Crosshair
    </div>
  </div>
);

export default function App() {
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [result, setResult] = useState<IPDResult | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Chat state
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [currentMessage, setCurrentMessage] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatMessages, isChatLoading]);

  const captureFrame = useCallback(async (isFinal = true) => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.9);

        if (isFinal) {
          setCapturedImage(dataUrl);
          if (videoRef.current.srcObject) {
            (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
          }
          processFinalImage(dataUrl);
        }
        return dataUrl;
      }
    }
    return null;
  }, []);

  const processFinalImage = async (dataUrl: string) => {
    try {
      setStatus('analyzing');
      const analysis = await analyzeIPD(dataUrl.split(',')[1]);
      setResult(analysis);
      setStatus('completed');
    } catch (err) {
      setError("Spatial reconstruction failed. Ensure lighting is uniform and you are looking directly at the crosshair.");
      setStatus('error');
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentMessage.trim() || isChatLoading || !result || !capturedImage) return;

    const userMsg = currentMessage;
    setCurrentMessage('');
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsChatLoading(true);

    try {
      const aiResponse = await chatWithExpert(
        userMsg, 
        chatMessages, 
        result.ipdMm, 
        capturedImage.split(',')[1]
      );
      setChatMessages(prev => [...prev, { role: 'model', text: aiResponse }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { role: 'model', text: "I'm sorry, I encountered an error connecting to my neural core. Please try again." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const startCamera = async () => {
    try {
      setStatus('capturing');
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      setError("Camera unavailable. Please check device permissions.");
      setStatus('idle');
    }
  };

  const reset = () => {
    setStatus('idle');
    setResult(null);
    setCapturedImage(null);
    setError(null);
    setChatMessages([]);
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
  };

  const isOutOfRange = result && (result.ipdMm < 59.5 || result.ipdMm > 75);

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 selection:bg-emerald-100">
      <Header />

      <main className="flex-grow max-w-6xl mx-auto w-full px-4 py-8 md:py-16">
        {status === 'idle' && (
          <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700">
            <div className="mb-12 md:mb-16">
              <div className="inline-flex items-center gap-2 px-3 py-1 bg-white border border-slate-200 rounded-full mb-6">
                <Sparkles size={12} className="text-emerald-500" />
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Advanced Spatial Sensors Ready</span>
              </div>
              <h1 className="text-5xl md:text-7xl font-black text-slate-900 mb-6 tracking-tight leading-[0.95]">
                Bio-Metric <br/>
                <span className="text-emerald-600">Manual-PD.</span>
              </h1>
              <p className="text-lg md:text-xl text-slate-500 leading-relaxed mb-10 max-w-xl">
                Clinical-grade measurement with spatial AI analysis. Validated accuracy powered by Gemini Spatial Intelligence.
              </p>

              <div className="flex flex-col sm:flex-row gap-4">
                <button 
                  onClick={startCamera}
                  className="px-10 py-5 bg-emerald-600 text-white font-bold rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
                >
                  <Camera size={24} className="group-hover:rotate-12 transition-transform" />
                  Launch Scanner
                </button>
                <div className="relative">
                  <input type="file" accept="image/*" onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const r = new FileReader();
                      r.onload = (ev) => { setCapturedImage(ev.target?.result as string); processFinalImage(ev.target?.result as string); };
                      r.readAsDataURL(file);
                    }
                  }} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                  <button className="w-full sm:w-auto px-10 py-5 bg-white text-slate-700 font-bold rounded-2xl border border-slate-200 hover:bg-slate-50 transition-all flex items-center justify-center gap-3 shadow-sm">
                    <Upload size={22} />
                    Upload Image
                  </button>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { icon: <Target className="text-emerald-600" />, title: "Precision Target", desc: "Align your gaze with the central crosshair for high-accuracy Far-PD measurement." },
                { icon: <Scan className="text-emerald-600" />, title: "Spatial Sync", desc: "Advanced facial mesh analysis ensures correct scaling without reference objects." },
                { icon: <ShieldCheck className="text-emerald-600" />, title: "Clinical Standards", desc: "Verified against ISO-13666 standards for ophthalmic measurements." }
              ].map((item, i) => (
                <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                  <div className="mb-4">{item.icon}</div>
                  <h3 className="font-bold text-slate-900 mb-2 uppercase text-[11px] tracking-wider">{item.title}</h3>
                  <p className="text-slate-500 leading-relaxed text-xs">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {status === 'capturing' && (
          <div className="max-w-4xl mx-auto animate-in zoom-in-95 duration-500 flex flex-col gap-8">
            <div className="relative aspect-[3/4] sm:aspect-video bg-slate-950 rounded-[3rem] overflow-hidden border-4 md:border-8 border-white shadow-2xl ring-1 ring-slate-100">
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover scale-x-[-1]" />

              <div className="absolute inset-0 pointer-events-none">
                <SpatialMeshOverlay />
                <div className="w-full h-full border-[20px] sm:border-[50px] md:border-[80px] border-black/40">
                  <div className="w-full h-full border-2 border-dashed border-white/10 rounded-[2.5rem] relative">
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[85%] sm:w-80 h-[45%] sm:h-56 border-2 border-emerald-400/20 rounded-[3rem] shadow-[0_0_50px_rgba(52,211,153,0.05)]" />
                    <div className="absolute top-0 left-0 right-0 h-0.5 bg-emerald-400/80 scanner-line" />
                  </div>
                </div>
              </div>

              <FixationTarget />

              {/* Live Tracking Overlay */}
              <div className="absolute top-6 left-6 right-6 flex justify-between items-start pointer-events-none">
                <div className="px-4 py-2 rounded-xl backdrop-blur-md border border-white/20 bg-black/40 text-white/70 flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-white/50 animate-pulse" />
                  <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                    Awaiting Manual Capture...
                  </span>
                </div>
              </div>
            </div>

            <div className="flex flex-col items-center gap-6">
              <div className="flex gap-4">
                <button 
                  onClick={() => captureFrame(true)}
                  className="px-12 py-5 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 hover:scale-105 active:scale-95 transition-all flex items-center gap-3"
                >
                  <Target size={24} />
                  Capture Now
                </button>
                <button 
                  onClick={reset} 
                  className="px-10 py-5 bg-white text-slate-700 font-bold rounded-2xl border border-slate-200 hover:bg-slate-50 transition-all shadow-sm"
                >
                  Cancel
                </button>
              </div>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest flex items-center gap-2">
                <Info size={14} className="text-emerald-500" />
                Hold steady and look at the crosshair before clicking
              </p>
            </div>
          </div>
        )}

        {status === 'analyzing' && (
          <div className="max-w-md mx-auto text-center py-24 flex flex-col items-center animate-in fade-in duration-700">
            <div className="w-24 h-24 relative mb-10">
              <div className="absolute inset-0 border-4 border-emerald-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-emerald-600 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <Activity size={32} className="text-emerald-600 animate-pulse" />
              </div>
            </div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter mb-4">Spatial Refinement</h2>
            <div className="space-y-2 text-slate-400 text-xs font-bold uppercase tracking-widest">
              <p>Thinking deeply about your facial mesh...</p>
              <p>Reconstructing 3D Spatial Lattice...</p>
              <p>Verifying Euclidean Gaze Axis...</p>
            </div>
          </div>
        )}

        {status === 'completed' && result && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 md:gap-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="lg:col-span-5 space-y-8">
              <div className="relative aspect-square bg-slate-900 rounded-[3rem] overflow-hidden shadow-2xl border-[8px] border-white group">
                <img src={capturedImage!} alt="Analysis" className="w-full h-full object-cover opacity-90" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent"></div>

                {/* Visualizer Overlays */}
                <div className="absolute w-5 h-5 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full bg-emerald-500 shadow-[0_0_20px_#10b981] z-20" style={{ left: `${result.rightPupilCenter[0]/10}%`, top: `${result.rightPupilCenter[1]/10}%` }}></div>
                <div className="absolute w-5 h-5 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full bg-emerald-500 shadow-[0_0_20px_#10b981] z-20" style={{ left: `${result.leftPupilCenter[0]/10}%`, top: `${result.leftPupilCenter[1]/10}%` }}></div>

                <svg className="absolute inset-0 w-full h-full pointer-events-none z-10">
                  <line x1={`${result.rightPupilCenter[0]/10}%`} y1={`${result.rightPupilCenter[1]/10}%`} x2={`${result.leftPupilCenter[0]/10}%`} y2={`${result.leftPupilCenter[1]/10}%`} stroke="white" strokeWidth="2" strokeDasharray="10,5" />
                </svg>

                <div className="absolute bottom-6 left-6 right-6 p-4 bg-black/40 backdrop-blur-xl rounded-2xl border border-white/10 flex justify-between items-center">
                  <div className="text-[10px] font-black text-white uppercase tracking-widest flex items-center gap-2">
                    <Target size={14} /> Clinical Audit Trail
                  </div>
                </div>
              </div>

              {/* AI Chat Consultation Interface */}
              <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden flex flex-col h-[500px]">
                <div className="p-6 border-b border-slate-50 bg-slate-50/50 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-emerald-100 rounded-xl flex items-center justify-center text-emerald-600">
                      <Sparkles size={20} />
                    </div>
                    <div>
                      <h4 className="text-sm font-black text-slate-900 uppercase tracking-tight leading-none">AI Consultant</h4>
                      <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Thinking Ready</span>
                    </div>
                  </div>
                </div>

                <div className="flex-grow overflow-y-auto p-6 space-y-4 bg-slate-50/20">
                  {chatMessages.length === 0 && (
                    <div className="text-center py-10 opacity-50">
                      <MessageSquare className="mx-auto mb-3 text-slate-300" size={32} />
                      <p className="text-xs font-bold uppercase tracking-widest text-slate-400 px-10 leading-relaxed">
                        Ask about frame recommendations or your IPD results
                      </p>
                    </div>
                  )}
                  {chatMessages.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[85%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm border ${
                        msg.role === 'user' 
                        ? 'bg-emerald-600 text-white border-emerald-500 rounded-tr-none' 
                        : 'bg-white text-slate-700 border-slate-100 rounded-tl-none'
                      }`}>
                        {msg.text}
                      </div>
                    </div>
                  ))}
                  {isChatLoading && (
                    <div className="flex justify-start">
                      <div className="bg-white p-4 rounded-2xl border border-slate-100 rounded-tl-none flex items-center gap-3">
                        <Loader2 className="animate-spin text-emerald-500" size={16} />
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest animate-pulse">Thinking...</span>
                      </div>
                    </div>
                  )}
                  <div ref={chatEndRef} />
                </div>

                <form onSubmit={handleSendMessage} className="p-4 bg-white border-t border-slate-50 flex gap-2">
                  <input
                    type="text"
                    value={currentMessage}
                    onChange={(e) => setCurrentMessage(e.target.value)}
                    placeholder="Ask about your vision..."
                    className="flex-grow bg-slate-50 border-none rounded-xl px-4 py-3 text-xs font-medium focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
                  />
                  <button 
                    disabled={!currentMessage.trim() || isChatLoading}
                    className="w-10 h-10 bg-emerald-600 text-white rounded-xl flex items-center justify-center hover:bg-emerald-700 disabled:opacity-50 disabled:bg-slate-400 transition-all shrink-0 shadow-lg shadow-emerald-100"
                  >
                    <Send size={18} />
                  </button>
                </form>
              </div>
            </div>

            <div className="lg:col-span-7 space-y-8">
              <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-xl border border-slate-100 relative overflow-hidden">
                <div className="flex items-center justify-between mb-8">
                  <span className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.2em]">Interpupillary Distance</span>
                  <div className={`px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${isOutOfRange ? 'bg-orange-100 text-orange-700' : 'bg-emerald-100 text-emerald-700'}`}>
                    {isOutOfRange ? 'Outside Standard' : 'Far-PD Verified'}
                  </div>
                </div>

                <div className="flex items-baseline gap-4 mb-10">
                  <span className={`text-9xl font-black tracking-tighter leading-none ${isOutOfRange ? 'text-orange-500' : 'text-slate-900'}`}>
                    {result.ipdMm.toFixed(1)}
                  </span>
                  <span className="text-3xl font-bold text-slate-200 italic uppercase">mm</span>
                </div>

                <div className="grid grid-cols-2 gap-6 mb-10">
                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Precision Scaling</span>
                    <div className="text-2xl font-black text-slate-800">{result.scalingFactor.toFixed(3)}</div>
                  </div>
                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Confidence Score</span>
                    <div className="text-2xl font-black text-emerald-600">{(result.confidence * 100).toFixed(1)}<span className="text-xs ml-0.5">%</span></div>
                  </div>
                </div>

                <div className="bg-slate-900 p-6 rounded-[2rem] flex flex-col sm:flex-row items-center justify-between gap-6">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-emerald-900/40">
                      <ShieldCheck size={24} />
                    </div>
                    <div>
                      <div className="text-white text-sm font-bold">Standard: ISO-13666 Clinical</div>
                      <div className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Model: Gemini 3 Pro (Thinking)</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 text-emerald-400 font-black text-xs uppercase tracking-widest bg-emerald-400/10 px-4 py-2 rounded-xl border border-emerald-400/20">
                    Validated
                    <CheckCircle size={14} />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <button 
                  onClick={reset} 
                  className="py-7 bg-emerald-600 text-white font-black text-xl rounded-[2.5rem] hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 shadow-2xl shadow-emerald-100 group"
                >
                  <RefreshCw size={24} className="group-hover:rotate-180 transition-transform duration-1000" />
                  New Scan
                </button>
                <button className="py-7 bg-white text-slate-900 font-bold text-lg rounded-[2.5rem] border-2 border-slate-100 hover:bg-slate-50 transition-all flex items-center justify-center gap-2">
                  <ChevronRight size={20} className="text-slate-300" />
                  Full Report
                </button>
              </div>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="max-w-xl mx-auto bg-white p-12 rounded-[3.5rem] border border-red-50 shadow-2xl text-center animate-in zoom-in-95 duration-500">
            <div className="w-20 h-20 bg-red-50 text-red-500 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-inner"><AlertCircle size={40} /></div>
            <h2 className="text-3xl font-black text-slate-900 mb-4 tracking-tight">Spatial Error</h2>
            <p className="text-slate-500 mb-10 leading-relaxed max-w-sm mx-auto">{error}</p>
            <button onClick={reset} className="w-full py-5 bg-slate-900 text-white font-bold rounded-2xl hover:bg-black transition-all">Try Again</button>
          </div>
        )}
      </main>

      <Footer />
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Camera, Upload, RefreshCw, Info, CheckCircle, AlertCircle, Target, Scan, ShieldCheck, Fingerprint, Activity, ChevronRight, Grid3X3, Layers, Sun, User, Minimize, Crosshair, Eye, Sparkles, MessageSquare, Send, Loader2, Zap } from 'lucide-react';
import { ScanStatus, IPDResult } from './types';
import { analyzeIPD, chatWithExpert, preCalibrateIPD } from './services/geminiService';

const Header = () => (
  <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-50">
    <div className="max-w-6xl mx-auto px-6 h-16 md:h-20 flex items-center justify-between">
      <div className="flex items-center gap-3">
        <div className="w-9 h-9 bg-emerald-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-emerald-100">
          <Fingerprint size={20} />
        </div>
        <div>
          <span className="font-bold text-lg tracking-tight text-slate-900 block leading-none">VisionMetric</span>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">TrueDepth Spatial Analysis</span>
        </div>
      </div>
      <div className="hidden md:flex items-center gap-4">
        <div className="px-3 py-1 bg-emerald-50 text-emerald-700 text-[10px] font-bold rounded-full border border-emerald-100 uppercase tracking-widest">
          Spatial Sync Active
        </div>
      </div>
    </div>
  </header>
);

const Footer = () => (
  <footer className="mt-auto py-8 px-6 border-t border-slate-100 bg-white">
    <div className="max-w-6xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4 text-slate-400 text-[11px] font-medium uppercase tracking-wider">
      <p>© 2026 VisionMetric Labs. 3D Spatial Reconstruction Protocol.</p>
      <div className="flex gap-6">
        <a href="#" className="hover:text-emerald-600 transition-colors">Privacy</a>
        <a href="#" className="hover:text-emerald-600 transition-colors">Terms</a>
      </div>
    </div>
  </footer>
);

const SpatialMeshOverlay = () => (
  <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-20">
    <div className="absolute inset-0" style={{ 
      backgroundImage: `radial-gradient(circle, #34d399 1px, transparent 1px)`, 
      backgroundSize: '30px 30px' 
    }} />
    <div className="w-full h-full animate-pulse flex items-center justify-center">
      <div className="w-[80%] h-[80%] border border-emerald-400/30 rounded-full" />
      <div className="absolute w-[60%] h-[60%] border border-emerald-400/20 rounded-full" />
    </div>
  </div>
);

const FixationTarget = () => (
  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center justify-center z-30 pointer-events-none">
    <div className="relative">
      <div className="w-16 h-16 border-2 border-white/20 rounded-full absolute inset-0 transition-all duration-500 scale-100" />
      <div className="w-16 h-16 border-2 border-white/40 rounded-full flex items-center justify-center backdrop-blur-sm bg-black/20">
        <Crosshair className="text-white/60 size-8" />
      </div>
    </div>
    <div className="mt-6 px-4 py-2 text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-full shadow-lg border bg-black/40 border-white/20 flex items-center gap-2">
      <Eye className="size-3" /> Fixate on Crosshair
    </div>
  </div>
);

export default function App() {
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [result, setResult] = useState<IPDResult | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Calibration / Live States
  const [isCalibrating, setIsCalibrating] = useState(false);
  const [calibratedIPD, setCalibratedIPD] = useState<number | null>(null);

  // Chat state
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [currentMessage, setCurrentMessage] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatMessages, isChatLoading]);

  const captureFrame = useCallback(async (isFinal = true) => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.9);

        if (isFinal) {
          setCapturedImage(dataUrl);
          if (videoRef.current.srcObject) {
            (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
          }
          processFinalImage(dataUrl);
        }
        return dataUrl;
      }
    }
    return null;
  }, []);

  const runAutoCalibration = async () => {
    if (status !== 'capturing' || isCalibrating) return;
    setIsCalibrating(true);
    try {
      // Small delay to allow camera to adjust exposure
      await new Promise(r => setTimeout(r, 800));
      const frame = await captureFrame(false);
      if (frame) {
        const estimate = await preCalibrateIPD(frame.split(',')[1]);
        setCalibratedIPD(estimate.ipdMm);
      }
    } catch (e) {
      console.error("Auto-calibration failed", e);
    } finally {
      setIsCalibrating(false);
    }
  };

  // Trigger calibration when camera starts
  useEffect(() => {
    if (status === 'capturing' && !calibratedIPD) {
      runAutoCalibration();
    }
  }, [status]);

  const processFinalImage = async (dataUrl: string) => {
    try {
      setStatus('analyzing');
      const analysis = await analyzeIPD(dataUrl.split(',')[1]);
      setResult(analysis);
      setStatus('completed');
    } catch (err) {
      setError("Spatial reconstruction failed. Ensure lighting is uniform and you are looking directly at the crosshair.");
      setStatus('error');
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentMessage.trim() || isChatLoading || !result || !capturedImage) return;

    const userMsg = currentMessage;
    setCurrentMessage('');
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsChatLoading(true);

    try {
      const aiResponse = await chatWithExpert(
        userMsg, 
        chatMessages, 
        result.ipdMm, 
        capturedImage.split(',')[1]
      );
      setChatMessages(prev => [...prev, { role: 'model', text: aiResponse }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { role: 'model', text: "I'm sorry, I encountered an error connecting to my neural core. Please try again." }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const startCamera = async () => {
    try {
      setStatus('capturing');
      setError(null);
      setCalibratedIPD(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      setError("Camera unavailable. Please check device permissions.");
      setStatus('idle');
    }
  };

  const reset = () => {
    setStatus('idle');
    setResult(null);
    setCapturedImage(null);
    setError(null);
    setChatMessages([]);
    setCalibratedIPD(null);
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
  };

  const isOutOfRange = result && (result.ipdMm < 59.5 || result.ipdMm > 75);

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 selection:bg-emerald-100">
      <Header />

      <main className="flex-grow max-w-6xl mx-auto w-full px-4 py-8 md:py-16">
        {status === 'idle' && (
          <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700">
            <div className="mb-12 md:mb-16">
              <div className="inline-flex items-center gap-2 px-3 py-1 bg-white border border-slate-200 rounded-full mb-6">
                <Sparkles size={12} className="text-emerald-500" />
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Advanced Spatial Sensors Ready</span>
              </div>
              <h1 className="text-5xl md:text-7xl font-black text-slate-900 mb-6 tracking-tight leading-[0.95]">
                Bio-Metric <br/>
                <span className="text-emerald-600">Spatial-PD.</span>
              </h1>
              <p className="text-lg md:text-xl text-slate-500 leading-relaxed mb-10 max-w-xl">
                Clinical-grade measurement with two-stage AI analysis. High-speed auto-calibration followed by deep spatial mapping.
              </p>

              <div className="flex flex-col sm:flex-row gap-4">
                <button 
                  onClick={startCamera}
                  className="px-10 py-5 bg-emerald-600 text-white font-bold rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
                >
                  <Camera size={24} className="group-hover:rotate-12 transition-transform" />
                  Launch Scanner
                </button>
                <div className="relative">
                  <input type="file" accept="image/*" onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const r = new FileReader();
                      r.onload = (ev) => { setCapturedImage(ev.target?.result as string); processFinalImage(ev.target?.result as string); };
                      r.readAsDataURL(file);
                    }
                  }} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                  <button className="w-full sm:w-auto px-10 py-5 bg-white text-slate-700 font-bold rounded-2xl border border-slate-200 hover:bg-slate-50 transition-all flex items-center justify-center gap-3 shadow-sm">
                    <Upload size={22} />
                    Upload Image
                  </button>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { icon: <Zap className="text-emerald-600" />, title: "Auto-Calibration", desc: "High-speed initial scan provides immediate feedback and stabilizes sensors." },
                { icon: <Target className="text-emerald-600" />, title: "Precision Target", desc: "Align your gaze with the central crosshair for high-accuracy Far-PD measurement." },
                { icon: <ShieldCheck className="text-emerald-600" />, title: "Clinical Standards", desc: "Verified against ISO-13666 standards for ophthalmic measurements." }
              ].map((item, i) => (
                <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                  <div className="mb-4">{item.icon}</div>
                  <h3 className="font-bold text-slate-900 mb-2 uppercase text-[11px] tracking-wider">{item.title}</h3>
                  <p className="text-slate-500 leading-relaxed text-xs">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {status === 'capturing' && (
          <div className="max-w-4xl mx-auto animate-in zoom-in-95 duration-500 flex flex-col gap-8">
            <div className="relative aspect-[3/4] sm:aspect-video bg-slate-950 rounded-[3rem] overflow-hidden border-4 md:border-8 border-white shadow-2xl ring-1 ring-slate-100">
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover scale-x-[-1]" />

              <div className="absolute inset-0 pointer-events-none">
                <SpatialMeshOverlay />
                <div className="w-full h-full border-[20px] sm:border-[50px] md:border-[80px] border-black/40">
                  <div className="w-full h-full border-2 border-dashed border-white/10 rounded-[2.5rem] relative">
