const IRDotProjector = ({ active, color = 'rgba(34, 197, 94' }: { active: boolean, color?: string }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!active || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frame = 0;
    const dots: { x: number, y: number, phase: number }[] = [];
    const rows = 45;
    const cols = 60;

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        dots.push({ x: (c / cols) * 100, y: (r / rows) * 100, phase: Math.random() * Math.PI * 2 });
      }
    }

    const animate = () => {
      frame++;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const w = canvas.width;
      const h = canvas.height;

      dots.forEach(dot => {
        const dx = dot.x - 50;
        const dy = dot.y - 50;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const warp = 1 + Math.sin(frame * 0.04 + dist * 0.12) * 0.03;

        const finalX = (dx * warp + 50) * (w / 100);
        const finalY = (dy * warp + 50) * (h / 100);

        ctx.fillStyle = `${color}, ${0.4 + Math.sin(frame * 0.1 + dot.phase) * 0.2})`;
        ctx.beginPath();
        ctx.arc(finalX, finalY, 1.3, 0, Math.PI * 2);
        ctx.fill();
      });

      requestAnimationFrame(animate);
    };

    const handle = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(handle);
  }, [active, color]);

  return <canvas ref={canvasRef} className={`absolute inset-0 pointer-events-none transition-opacity duration-1000 ${active ? 'opacity-70' : 'opacity-0'}`} width={1000} height={1000} />;
};

export default function App() {
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [result, setResult] = useState<IPDResult | null>(null);
  const [authResult, setAuthResult] = useState<BiometricResult | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isCalibrating, setIsCalibrating] = useState(false);
  const [calibratedIPD, setCalibratedIPD] = useState<number | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const captureFrame = useCallback(async (isFinal = true) => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.9);
        if (isFinal) {
          setCapturedImage(dataUrl);
          if (videoRef.current.srcObject) {
            (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
          }
        }
        return dataUrl;
      }
    }
    return null;
  }, []);

  const runIPDAnalysis = async () => {
    setStatus('analyzing');
    const frame = await captureFrame(true);
    if (frame) {
      try {
        const res = await analyzeIPD(frame.split(',')[1]);

        // REQUIREMENT: The final result should be the pre-scan estimate + 5mm
        // Fallback to model's detected IPD + 5 if pre-scan isn't available
        const baseEstimate = calibratedIPD !== null ? calibratedIPD : res.ipdMm;
        const finalIpd = baseEstimate + 5;

        setResult({
          ...res,
          ipdMm: finalIpd,
          explanation: `${res.explanation} (Note: Result adjusted by +5mm spatial offset rule as requested).`
        });
        setStatus('completed');
      } catch (e) {
        setError("Spatial analysis failed. Ensure the IR mesh is fully visible on your face.");
        setStatus('error');
      }
    }
  };

  const runAuthentication = async () => {
    setStatus('authenticating');
    const frame = await captureFrame(true);
    if (frame) {
      try {
        const res = await verifyBiometricIdentity(frame.split(',')[1]);
        setAuthResult(res);
        if (res.verified) {
          setStatus('authorized');
        } else {
